import{S as e,g as t,h as n,l as r,m as i,r as a,s as o}from"./hooks--ohl3fRn.js";import{t as s}from"./index-CwzTUgb-.js";var c=r(),l=`[наименование и УНП оператора сервиса — заполняется перед запуском]`,u={offer:{tab:`Оферта`,title:`Публичная оферта (пользовательское соглашение)`,body:(0,c.jsxs)(c.Fragment,{children:[(0,c.jsxs)(`p`,{className:`muted`,children:[`Проект редакции. Оператор сервиса: `,l,`.`]}),(0,c.jsx)(`h2`,{children:`1. Предмет`}),(0,c.jsx)(`p`,{children:`1.1. Настоящая оферта — предложение заключить договор об использовании сервиса AutoInvest (далее — Сервис) на изложенных условиях. Договор заключается с момента регистрации и проставления отметки о принятии оферты (ст. 405, 407, 408 Гражданского кодекса Республики Беларусь).`}),(0,c.jsx)(`p`,{children:`1.2. Сервис — программный инструмент, который по поручению пользователя регулярно инициирует списание выбранной суммы с привязанной банковской карты и передаёт поручение на покупку цифровых знаков (токенов) лицензированному партнёру.`}),(0,c.jsx)(`h2`,{children:`2. Модель работы: Сервис не хранит деньги и активы`}),(0,c.jsx)(`p`,{children:`2.1. Сервис работает по некастодиальной модели. Он не является банком, небанковской кредитно-финансовой организацией, оператором криптоплатформы, оператором обмена криптовалют, брокером или доверительным управляющим, не принимает денежные средства во вклады и не хранит токены пользователей.`}),(0,c.jsx)(`p`,{children:`2.2. Платежи по картам обрабатывает платёжный агрегатор bePaid. Сделки с токенами совершает оператор криптоплатформы или оператор обмена криптовалют — резидент Парка высоких технологий (например, ЗАО «Уайт Бёрд»). Учёт токенов ведётся у такого оператора, с которым пользователь заключает отдельный договор.`}),(0,c.jsx)(`p`,{children:`2.3. Ответственность разграничена: за проведение платежа отвечает платёжный агрегатор и банк-эмитент; за исполнение сделки и хранение токенов — оператор-резидент ПВТ; за корректную передачу поручений в соответствии с настройками пользователя — Сервис.`}),(0,c.jsx)(`p`,{children:`2.4. Пока договор с оператором-резидентом ПВТ не заключён, пополнения с карты не принимаются: Пользователь может настроить копилку и встать в лист ожидания, а также воспользоваться демо-счётом с виртуальными деньгами, где покупки учитываются по реальным биржевым ценам, но не исполняются. Демо-счёт отмечен в интерфейсе и в каждом чеке.`}),(0,c.jsx)(`h2`,{children:`3. Копилки и поручения`}),(0,c.jsx)(`p`,{children:`3.1. Создавая копилку, пользователь даёт длящееся поручение на периодические списания и покупки по заданным сумме, расписанию и составу активов. Поручение действует до изменения, приостановки или закрытия копилки пользователем.`}),(0,c.jsx)(`p`,{children:`3.2. Цена покупки — биржевая котировка на момент исполнения с учётом спреда оператора. Стоимость в белорусских рублях считается по официальному курсу Национального банка на дату операции.`}),(0,c.jsx)(`h2`,{children:`4. Вознаграждение`}),(0,c.jsx)(`p`,{children:`4.1. Комиссия Сервиса за пополнение и стоимость подписки Pro указаны на сайте и в чеке каждой операции. Об изменении тарифов Сервис уведомляет не позднее чем за 14 дней.`}),(0,c.jsx)(`h2`,{children:`5. Вывод средств`}),(0,c.jsx)(`p`,{children:`5.1. Пользователь в любой момент вправе поручить продажу активов копилки и перечисление денег на свою карту. Срок зачисления зависит от оператора и банка-эмитента.`}),(0,c.jsx)(`h2`,{children:`6. Ответственность и риски`}),(0,c.jsxs)(`p`,{children:[`6.1. Сервис не гарантирует доход и не возмещает убытки от изменения рыночной стоимости активов. Пользователь подтверждает, что ознакомлен с `,(0,c.jsx)(i,{to:`/legal/risks`,children:`Уведомлением о рисках`}),`.`]}),(0,c.jsx)(`p`,{children:`6.2. Пользователь отвечает за сохранность доступа к аккаунту. Сервис рекомендует включить двухфакторную защиту.`}),(0,c.jsx)(`h2`,{children:`7. Прекращение`}),(0,c.jsx)(`p`,{children:`7.1. Пользователь вправе расторгнуть договор, удалив аккаунт в профиле после вывода средств. Сервис вправе приостановить доступ при нарушении законодательства или настоящей оферты.`}),(0,c.jsx)(`h2`,{children:`8. Применимое право`}),(0,c.jsx)(`p`,{children:`8.1. К договору применяется право Республики Беларусь. Споры разрешаются в претензионном порядке, а при недостижении согласия — в суде по месту нахождения оператора Сервиса.`})]})},privacy:{tab:`Персональные данные`,title:`Политика обработки персональных данных`,body:(0,c.jsxs)(c.Fragment,{children:[(0,c.jsxs)(`p`,{className:`muted`,children:[`Проект редакции, подготовлен в соответствии с Законом Республики Беларусь от 7 мая 2021 г. № 99-З «О защите персональных данных». Оператор: `,l,`.`]}),(0,c.jsx)(`h2`,{children:`1. Какие данные мы обрабатываем`}),(0,c.jsxs)(`ul`,{children:[(0,c.jsx)(`li`,{children:`При регистрации: имя, адрес электронной почты, номер телефона (по желанию).`}),(0,c.jsx)(`li`,{children:`При верификации: фамилия, имя, отчество, дата рождения, серия и номер паспорта, идентификационный номер, гражданство, адрес, изображение документа и фото с документом.`}),(0,c.jsx)(`li`,{children:`При работе с сервисом: настройки копилок, операции, чеки, обращения в поддержку.`}),(0,c.jsx)(`li`,{children:`Технические данные: IP-адрес, тип браузера и устройства, время входов — для защиты аккаунта.`})]}),(0,c.jsx)(`p`,{children:`Номер карты, срок действия и CVC Сервис не получает и не хранит: их вводят на защищённой странице платёжного агрегатора (сертификат PCI DSS). У нас остаются только токен карты, первые шесть и последние четыре цифры номера, срок действия и название банка.`}),(0,c.jsx)(`h2`,{children:`2. Цели и правовые основания`}),(0,c.jsxs)(`ul`,{children:[(0,c.jsx)(`li`,{children:`Исполнение договора (оферты): ведение копилок, передача поручений, чеки — ст. 6 Закона № 99-З.`}),(0,c.jsx)(`li`,{children:`Идентификация клиентов по законодательству о предотвращении легализации доходов, полученных преступным путём.`}),(0,c.jsx)(`li`,{children:`Защита аккаунта от несанкционированного доступа.`}),(0,c.jsx)(`li`,{children:`Информационные рассылки — только с отдельного согласия, которое можно выключить в профиле.`})]}),(0,c.jsx)(`h2`,{children:`3. Согласие`}),(0,c.jsx)(`p`,{children:`Согласие даётся отдельной отметкой при регистрации, свободно и однозначно. Мы храним, когда, с какого IP-адреса и на какую редакцию политики оно дано. Согласие можно отозвать, удалив аккаунт в профиле или написав в поддержку; после отзыва обработка прекращается, кроме случаев, когда хранение требует закон.`}),(0,c.jsx)(`h2`,{children:`4. Кому передаются данные`}),(0,c.jsx)(`p`,{children:`Платёжному агрегатору и оператору криптоплатформы — в объёме, необходимом для исполнения операций; поставщикам рассылок и хостинга — по договорам поручения; государственным органам — в случаях, предусмотренных законом.`}),(0,c.jsx)(`h2`,{children:`5. Трансграничная передача`}),(0,c.jsx)(`p`,{children:`Если сервер, почтовый сервис или Telegram находятся за пределами Республики Беларусь, данные передаются за рубеж. В странах, не обеспечивающих надлежащий уровень защиты, передача возможна только с согласия пользователя (ст. 9 Закона № 99-З). О рисках такой передачи мы предупреждаем: в этих странах может не быть органа по защите данных и механизма судебной защиты прав субъекта. Подключая уведомления в Telegram, пользователь соглашается на передачу своего идентификатора чата компании Telegram.`}),(0,c.jsx)(`h2`,{children:`6. Сроки хранения`}),(0,c.jsx)(`p`,{children:`Данные аккаунта — пока действует договор. Сведения об операциях и данные идентификации — в течение сроков, установленных законодательством о бухгалтерском учёте и о предотвращении легализации доходов (не менее 5 лет после прекращения отношений). Журнал входов — 1 год.`}),(0,c.jsx)(`h2`,{children:`7. Ваши права (глава 3 Закона № 99-З)`}),(0,c.jsxs)(`ul`,{children:[(0,c.jsx)(`li`,{children:`Получить информацию об обработке своих данных — кнопка «Скачать мои данные» в профиле выгружает их одним файлом.`}),(0,c.jsx)(`li`,{children:`Потребовать исправить неточные данные — в профиле или через поддержку.`}),(0,c.jsx)(`li`,{children:`Получить сведения о передаче данных третьим лицам.`}),(0,c.jsx)(`li`,{children:`Отозвать согласие и потребовать прекратить обработку и удалить данные.`}),(0,c.jsx)(`li`,{children:`Обжаловать действия оператора в Национальный центр защиты персональных данных.`})]}),(0,c.jsx)(`p`,{children:`Обращения принимаются в разделе «Поддержка» и по адресу support@autoinvest.by. Отвечаем в сроки, установленные Законом № 99-З.`}),(0,c.jsx)(`h2`,{children:`8. Файлы cookie`}),(0,c.jsx)(`p`,{children:`Сервис использует только необходимые cookie: сеанс входа и защиту от подделки запросов. Рекламных и аналитических cookie нет.`})]})},risks:{tab:`Риски`,title:`Уведомление о рисках инвестирования в цифровые знаки (токены)`,body:(0,c.jsxs)(c.Fragment,{children:[(0,c.jsx)(`p`,{children:`Перед тем как пользоваться Сервисом, внимательно прочитайте это уведомление. Подтверждая его при регистрации, вы подтверждаете, что понимаете описанные риски.`}),(0,c.jsx)(`h2`,{children:`Нет гарантий и страхования`}),(0,c.jsx)(`p`,{children:`Цифровые знаки (токены) — не вклад. Средства в копилках не застрахованы Агентством по гарантированному возмещению банковских вкладов (вкладов) физических лиц, государство не гарантирует их возврат. Доход не гарантирован, вы можете получить обратно меньше, чем вложили, вплоть до полной потери.`}),(0,c.jsx)(`h2`,{children:`Рыночный риск и волатильность`}),(0,c.jsx)(`p`,{children:`Цены криптовалют резко меняются. Биткоин в отдельные годы терял 70–80% от пика, менее крупные криптовалюты — более 90%. Токены, привязанные к акциям, повторяют падения фондового рынка: индекс S&P 500 в кризисы снижался на 30–50%.`}),(0,c.jsx)(`h2`,{children:`Валютный риск`}),(0,c.jsx)(`p`,{children:`Стоимость показывается в белорусских рублях по официальному курсу НБРБ. Укрепление рубля уменьшает рублёвую стоимость долларовых активов, даже если в долларах она не изменилась.`}),(0,c.jsx)(`h2`,{children:`Риск контрагентов и ликвидности`}),(0,c.jsx)(`p`,{children:`Активы покупаются и учитываются у оператора-резидента ПВТ. Сбои в работе оператора, банка или платёжного агрегатора, а также банкротство эмитента токена могут задержать операции или привести к потерям. Токены с фиксированной доходностью не всегда можно продать досрочно.`}),(0,c.jsx)(`h2`,{children:`Регуляторный и налоговый риск`}),(0,c.jsx)(`p`,{children:`Законодательство о цифровых знаках, в том числе налоговое, меняется. Новые правила могут ограничить доступные операции или изменить налогообложение.`}),(0,c.jsx)(`h2`,{children:`Технологический риск`}),(0,c.jsx)(`p`,{children:`Возможны сбои, ошибки программного обеспечения и кибератаки. Защитите аккаунт двухфакторной аутентификацией.`}),(0,c.jsx)(`h2`,{children:`Прошлая доходность`}),(0,c.jsx)(`p`,{children:`Результаты калькулятора рассчитаны на исторических данных и не гарантируют результат в будущем. Сервис не даёт индивидуальных инвестиционных рекомендаций: подбор плана по анкете — справочный, решение принимаете вы.`})]})},tax:{tab:`Налоги`,title:`Налоги: гид по Декрету № 8`,body:(0,c.jsxs)(c.Fragment,{children:[(0,c.jsxs)(`p`,{className:`muted`,children:[`Справочный материал, не налоговая консультация. Изложено по состоянию на ноябрь 2026 года по разъяснению МНС: `,(0,c.jsx)(`a`,{href:`https://pravo.by/novosti/analitika/2025/august/89905/`,target:`_blank`,rel:`noreferrer`,children:`«О порядке налогообложения доходов физлиц, полученных от операций с цифровыми знаками»`}),` (pravo.by, август 2025). Правила меняются — перед подачей декларации сверяйтесь с налоговой инспекцией.`]}),(0,c.jsx)(`h2`,{children:`Коротко`}),(0,c.jsx)(`p`,{children:`Если вы покупаете и продаёте токены через резидента Парка высоких технологий (оператора криптоплатформы или оператора обмена криптовалют), подоходный налог с дохода от этих операций не платится. Именно так устроен Сервис после подключения партнёра-резидента ПВТ.`}),(0,c.jsx)(`h2`,{children:`Что не облагается подоходным налогом`}),(0,c.jsxs)(`ul`,{children:[(0,c.jsx)(`li`,{children:`Доходы от операций с токенами через резидентов ПВТ.`}),(0,c.jsx)(`li`,{children:`Доходы от токенов, созданных резидентами ПВТ.`}),(0,c.jsx)(`li`,{children:`Майнинг и обмен одних токенов на другие.`}),(0,c.jsx)(`li`,{children:`Токены, полученные в наследство, и дары от близких родственников; от прочих физлиц — в пределах годового лимита.`})]}),(0,c.jsx)(`h2`,{children:`Что облагается`}),(0,c.jsxs)(`ul`,{children:[(0,c.jsxs)(`li`,{children:[(0,c.jsx)(`b`,{children:`13%`}),` — доходы от разрешённых операций через зарубежные площадки, иностранные организации, ИП и физлиц. Налог платите сами по декларации, которую подают до 31 марта следующего года.`]}),(0,c.jsxs)(`li`,{children:[(0,c.jsx)(`b`,{children:`26%`}),` — доходы от незаконных операций, например продажа токенов за деньги на иностранной криптобирже физлицом, находящимся в Беларуси, или через счёт в белорусском банке.`]})]}),(0,c.jsx)(`h2`,{children:`Как считается доход`}),(0,c.jsx)(`p`,{children:`Доход в токенах пересчитывается в рубли по курсу, который МНС определяет по данным резидентов ПВТ на каждый день (постановление Совета Министров № 280, действует с 24.08.2025).`}),(0,c.jsx)(`h2`,{children:`Что делать вам`}),(0,c.jsxs)(`ul`,{children:[(0,c.jsx)(`li`,{children:`Сохраняйте выписки: в разделе «Операции» есть выгрузка CSV для Excel и печатная выписка с курсом НБРБ на дату каждой сделки.`}),(0,c.jsx)(`li`,{children:`Пока Сервис работает в учебном режиме, реальных сделок и дохода нет, декларировать нечего.`}),(0,c.jsx)(`li`,{children:`Если покупаете криптовалюту на зарубежных площадках помимо Сервиса — эти доходы декларируются отдельно.`})]})]})}},d=[`offer`,`privacy`,`risks`,`tax`];function f(){let{doc:r=``}=e(),{config:l}=o(),f=u[r];return a(f?.title||``),r===`terms`?(0,c.jsx)(t,{to:`/legal/offer`,replace:!0}):f?(0,c.jsx)(`div`,{className:`wrapx`,children:(0,c.jsxs)(`article`,{className:`legal-doc`,children:[(0,c.jsx)(`nav`,{className:`legal-tabs`,"aria-label":`Документы`,children:d.map(e=>(0,c.jsx)(n,{to:`/legal/${e}`,children:u[e].tab},e))}),(0,c.jsx)(`h1`,{children:f.title}),l?.legal_version&&r!==`tax`&&(0,c.jsxs)(`p`,{className:`small muted`,children:[`Редакция от `,l.legal_version.split(`-`).reverse().join(`.`)]}),f.body,(0,c.jsx)(`p`,{className:`mt32`,children:(0,c.jsx)(i,{to:`/`,children:`На главную`})})]})}):(0,c.jsx)(s,{})}export{f as default};